// --- Quote edge cases ---

#[test]
fn handles_empty_double_quoted_value() {
    let content = r#"KEY="""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"".to_string()));
}

#[test]
fn handles_empty_single_quoted_value() {
    let content = "KEY=''";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"".to_string()));
}

#[test]
fn mismatched_quotes_not_stripped() {
    // Starting with double, ending with single should NOT unquote
    let content = r#"KEY="value'"#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
}

#[test]
fn mismatched_quotes_single_double() {
    let content = "KEY='value\"";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"'value\"".to_string()));
}

#[test]
fn single_double_quote_char_not_stripped() {
    // A lone " is not a pair of quotes
    let content = r#"KEY=""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
}

#[test]
fn single_single_quote_char_not_stripped() {
    let content = "KEY='";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
}

#[test]
fn quotes_embedded_in_unquoted_value() {
    let content = r#"KEY=some"value"here"#;
    let vars = EnvFileParser::parse(content).unwrap();
    // Not matching start+end quote, so kept as-is
    assert_eq!(vars.get("KEY"), Some(&r#"some"value"here"#.to_string()));
}

#[test]
fn preserves_inner_quotes_in_double_quoted_value() {
    let content = r#"KEY="it's a test""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"it's a test".to_string()));
}

#[test]
fn preserves_inner_double_quotes_in_single_quoted_value() {
    let content = r#"KEY='say "hello"'"#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r#"say "hello""#.to_string()));
}

#[test]
fn whitespace_preserved_inside_quotes() {
    let content = r#"KEY="  leading and trailing  ""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(
        vars.get("KEY"),
        Some(&"  leading and trailing  ".to_string())
    );
}

// --- Escaped character edge cases ---

#[test]
fn backslash_n_in_double_quotes_kept_literal() {
    // The parser does NOT interpret escape sequences — \n stays as literal \n
    let content = r#"KEY="line1\nline2""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r"line1\nline2".to_string()));
}

#[test]
fn backslash_in_unquoted_value() {
    let content = r"KEY=C:\Users\test";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r"C:\Users\test".to_string()));
}

#[test]
fn escaped_quote_inside_double_quotes_not_handled() {
    // The parser does NOT handle \" escape — the first " after opening starts a mismatch
    let content = r#"KEY="value with \"escaped\" quotes""#;
    let vars = EnvFileParser::parse(content).unwrap();
    // Because unquote sees starts_with(") and ends_with("), it strips outer quotes,
    // resulting in: value with \"escaped\" quotes
    let val = vars.get("KEY").unwrap();
    assert!(val.contains("\\\"escaped\\\""));
}

#[test]
fn backslash_at_end_of_value() {
    let content = r"KEY=value\";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r"value\".to_string()));
}

#[test]
fn tab_characters_in_quoted_value() {
    let content = "KEY=\"hello\tworld\"";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"hello\tworld".to_string()));
}

// --- Key edge cases ---

#[test]
fn key_with_leading_trailing_spaces_trimmed() {
    let content = "  MY_KEY  =value";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("MY_KEY"), Some(&"value".to_string()));
}

#[test]
fn duplicate_keys_last_wins() {
    let content = "KEY=first\nKEY=second";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
}

#[test]
fn key_with_numbers_and_underscores() {
    let content = "MY_VAR_123=value";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("MY_VAR_123"), Some(&"value".to_string()));
}

// --- Value edge cases ---

#[test]
fn value_with_multiple_equals_signs() {
    let content = "KEY=a=b=c=d";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
}

#[test]
fn value_with_hash_not_treated_as_comment() {
    // Inline comments are NOT stripped — the # is part of the value
    let content = "KEY=value#not-a-comment";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"value#not-a-comment".to_string()));
}

#[test]
fn value_with_spaces_and_hash() {
    let content = "KEY=value # this looks like a comment";
    let vars = EnvFileParser::parse(content).unwrap();
    // The parser doesn't strip inline comments
    assert_eq!(
        vars.get("KEY"),
        Some(&"value # this looks like a comment".to_string())
    );
}

#[test]
fn quoted_value_containing_hash() {
    let content = r#"KEY="value # with hash""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"value # with hash".to_string()));
}

#[test]
fn value_only_whitespace() {
    let content = "KEY=   ";
    let vars = EnvFileParser::parse(content).unwrap();
    // Value is trimmed, so becomes empty
    assert_eq!(vars.get("KEY"), Some(&"".to_string()));
}

#[test]
fn quoted_value_only_whitespace() {
    let content = r#"KEY="   ""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"   ".to_string()));
}

// --- Comment edge cases ---

#[test]
fn comment_with_equals_sign_ignored() {
    let content = "# KEY=value\nREAL=yes";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.len(), 1);
    assert_eq!(vars.get("REAL"), Some(&"yes".to_string()));
}

#[test]
fn indented_comment_skipped() {
    let content = "  # indented comment\nKEY=value";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.len(), 1);
}

// --- Whitespace / formatting edge cases ---

#[test]
fn windows_line_endings() {
    let content = "KEY1=value1\r\nKEY2=value2\r\n";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY1"), Some(&"value1".to_string()));
    assert_eq!(vars.get("KEY2"), Some(&"value2".to_string()));
